    drugs: ["talicabtagene-autoleucel"], cancers: ["dlbcl", "all-leukemia"], targets: ["cd19"], technologies: ["car-t"], companies: ["immunoact"], institutions: ["tata-memorial", "actrec", "iit-bombay"], people: ["jain-hasmukh", "narula-gaurav", "purwar-rahul"], keyPapers: ["paper-jain-talicabtagene-lancet-haem-2025"], terms: ["orr", "crs"], bottlenecks: ["b-manufacturing-cell-therapy", "b-global-access"],
